<?php get_header(); while(have_posts()):the_post(); $id=get_the_ID(); $cities=wp_get_post_terms($id,'bsktv_city',array('fields'=>'names')); $types=wp_get_post_terms($id,'bsktv_type',array('fields'=>'names')); ?>
<main class="single-page"><article>
<header class="store-hero-detail"><div class="store-hero-image"><?php if(has_post_thumbnail())the_post_thumbnail('full',array('fetchpriority'=>'high'));else echo '<div class="store-card-placeholder">BSKTV</div>'; ?><div class="store-hero-overlay"></div></div><div class="container store-hero-content"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">首頁</a><span>/</span><?php echo esc_html(implode('、',$cities)); ?></div><div class="store-kicker"><?php echo esc_html(implode(' · ',$types)); ?></div><h1><?php the_title(); ?></h1><?php if($p=bsktv_meta('bsktv_price'))echo '<div class="hero-price">'.esc_html($p).'</div>'; ?><div class="hero-actions"><button class="btn btn-gold" type="button" data-favorite data-id="'.esc_attr($id).'">♡ 收藏店家</button></div></div></header>
<div class="container section"><div class="single-layout"><div class="article-main"><div class="article-meta"><span>更新於 <?php echo esc_html(get_the_modified_date()); ?></span><span><?php echo esc_html(bsktv_views($id)); ?> 次瀏覽</span></div><div class="article-content"><?php the_content(); ?></div><?php $base=(float)bsktv_meta('bsktv_base_price');$person=(float)bsktv_meta('bsktv_person_price');$hour=(float)bsktv_meta('bsktv_hour_price');$fee=(float)bsktv_meta('bsktv_service_fee');if($base||$person||$hour): ?><section class="calculator" data-calculator data-base="<?php echo esc_attr($base); ?>" data-person="<?php echo esc_attr($person); ?>" data-hour="<?php echo esc_attr($hour); ?>" data-fee="<?php echo esc_attr($fee); ?>"><span class="eyebrow">QUICK ESTIMATE</span><h2>消費快速試算</h2><div class="calc-grid"><label>人數<input type="number" min="1" value="2" data-calc-person></label><label>時數<input type="number" min="1" value="2" data-calc-hour></label></div><div class="calc-result">預估金額 <strong data-calc-result>—</strong></div><small>僅為快速估算，實際消費依店家現場規定為準。</small></section><?php endif; ?></div><aside class="store-info"><div class="info-sticky"><div class="info-title"><span class="eyebrow">STORE INFO</span><h2>店家資訊</h2></div><?php $fields=array('bsktv_address'=>'地址','bsktv_hours'=>'營業時間','bsktv_phone'=>'電話','bsktv_line'=>'LINE／聯絡方式','bsktv_model'=>'消費模式','bsktv_room'=>'包廂資訊');foreach($fields as $k=>$label){$v=bsktv_meta($k);if($v)echo '<div class="info-row"><span class="info-label">'.esc_html($label).'</span><span>'.esc_html($v).'</span></div>';}if($phone=bsktv_meta('bsktv_phone'))echo '<a class="btn btn-primary btn-full" href="tel:'.esc_attr(preg_replace('/[^0-9+]/','',$phone)).'">電話聯絡</a>';if($line=bsktv_meta('bsktv_line'))echo '<div class="contact-line">'.esc_html($line).'</div>'; ?></div></aside></div></div></article><?php get_template_part('template-parts/related'); ?></main><?php endwhile; get_footer(); ?>
